const questions: BankQuestion[] = [
  {"id": "reason-inequality-order-1", "question": "If A > B ≥ C, which of the following is definitely true?", "options": ["A > C", "C > A", "B > A", "C ≥ B"], "answer": 0, "explanation": "A > B and B ≥ C chain to A > C; nothing allows C to exceed or equal A.", "difficulty": "easy", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-2", "question": "In a row of 30 students, Riya is 12th from the left end. What is her position from the right end?", "options": ["18th", "20th", "19th", "17th"], "answer": 2, "explanation": "Position from right = total − position from left + 1 = 30 − 12 + 1 = 19.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-3", "question": "A is taller than B, B is taller than C, and D is shorter than C. Who is the shortest?", "options": ["B", "C", "D", "A"], "answer": 2, "explanation": "The order is A > B > C > D, so D is the shortest.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-4", "question": "Which symbol should replace ? so that P > R is definitely true in the expression P > Q ? R?", "options": ["≤", "≥", "<", "No symbol can make it true"], "answer": 1, "explanation": "With ≥ the chain P > Q ≥ R gives P > R; with < or ≤, R could be larger than Q and possibly than P.", "difficulty": "easy", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-5", "question": "In a class, Mohit is 15th from the top and 26th from the bottom. How many students are in the class?", "options": ["41", "42", "40", "39"], "answer": 2, "explanation": "Total = 15 + 26 − 1 = 40 (Mohit is counted in both ranks, so subtract 1).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-6", "question": "In a row, A is 10th from the left and B is 14th from the right. Six persons sit between A and B, and A is to the left of B. How many persons are in the row?", "options": ["29", "30", "31", "18"], "answer": 1, "explanation": "B is at 10 + 6 + 1 = 17 from the left, so total = 17 + 14 − 1 = 30.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-7", "question": "Statement: P ≥ Q > R = S < T. Conclusions: I. P > S  II. T > R", "options": ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Both I and II follow"], "answer": 3, "explanation": "P ≥ Q > R = S gives P > S (I), and T > S = R gives T > R (II); both follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-8", "question": "P # Q means P is not greater than Q; P @ Q means P is neither smaller than nor equal to Q; P $ Q means P is not smaller than Q. If A @ B and B $ C, which conclusion definitely follows?", "options": ["A @ C", "A # C", "C @ A", "C $ A"], "answer": 0, "explanation": "A @ B is A > B and B $ C is B ≥ C, so A > C, which is A @ C; the other three would need C ≥ A or A ≤ C.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-9", "question": "Among five boxes P, Q, R, S and T, P is heavier than Q but lighter than R. S is heavier than R, and T is the lightest. Which box is the third heaviest?", "options": ["P", "Q", "S", "R"], "answer": 0, "explanation": "S > R > P > Q > T, so the third heaviest is P.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-10", "question": "Statement: M ≤ N = O ≥ P. Conclusions: I. M > P  II. M ≤ P", "options": ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither I nor II follows"], "answer": 2, "explanation": "M and P are both linked to N = O through opposite signs, so their relation is unknown; but I and II together cover every case and only one can hold, so either I or II follows.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-11", "question": "In a row, A is 8th from the left and B is 12th from the right. When they interchange places, A becomes 15th from the left. How many persons are in the row?", "options": ["27", "23", "25", "26"], "answer": 3, "explanation": "After the swap A stands where B was, so B’s seat is 15th from the left and 12th from the right: total = 15 + 12 − 1 = 26.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-12", "question": "Among A, B, C, D and E, A is taller than only C. B is shorter than D but taller than E, and E is taller than A. Who is the tallest?", "options": ["D", "A", "B", "E"], "answer": 0, "explanation": "A is taller than only C, so C < A < the rest. E > A, B > E and D > B give C < A < E < B < D, so D is the tallest.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-13", "question": "Statements: J > K ≥ L, M ≤ L < N, O = M. Conclusions: I. J > O  II. K > N", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "J > K ≥ L ≥ M = O gives J > O. K ≥ L and N > L share only L with opposite signs, so K versus N is unknown; only I follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-14", "question": "P % Q means P ≥ Q; P & Q means P > Q; P @ Q means P ≤ Q; P # Q means P < Q; P $ Q means P = Q. Statements: R & S, S $ T, T @ U. Conclusions: I. R & T  II. U # S", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Decoded: R > S = T ≤ U. Then R > T, so I follows; U ≥ T = S makes U < S false, so II does not follow.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-15", "question": "In a class of 50 students, Ankit is 18th from the top. Bina is 7 ranks below Ankit. What is Bina’s rank from the bottom?", "options": ["27th", "26th", "25th", "24th"], "answer": 1, "explanation": "Bina is 18 + 7 = 25th from the top, so from the bottom she is 50 − 25 + 1 = 26th.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-16", "question": "Among six friends, A is heavier than B and C. D is lighter than C but heavier than E. F is heavier than A, B is heavier than D, and C is heavier than B. Who is the third heaviest?", "options": ["Cannot be determined", "C", "A", "B"], "answer": 1, "explanation": "F > A > C > B > D > E: A beats B and C, C beats B, B beats D, D beats E. The third heaviest is C.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-17", "question": "In a row of boys, P is 14th from the left and Q is 19th from the right. When they interchange places, P becomes 21st from the left. How many boys sit between P and Q?", "options": ["8", "5", "7", "6"], "answer": 3, "explanation": "Q’s original seat is 21st from the left (P now sits there). The boys between seats 14 and 21 are 15 to 20: 6 boys. (The row has 21 + 19 − 1 = 39 boys.)", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-18", "question": "In a queue, R is 10th from the front and S is 25th from the back. Exactly 8 persons stand between R and S. What is the minimum possible number of persons in the queue?", "options": ["43", "26", "34", "25"], "answer": 3, "explanation": "If S is behind R, S is 19th from the front and the queue has 19 + 25 − 1 = 43. If S is ahead, S is 10 − 9 = 1st from the front, giving 1 + 25 − 1 = 25. The minimum is 25.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-19", "question": "Which of the following expressions makes ‘P > T’ definitely true?", "options": ["P > Q = R < S ≥ T", "T ≤ S < R ≥ Q ≥ P", "P > Q ≥ R = S ≥ T", "P ≥ Q > R ≤ S > T"], "answer": 2, "explanation": "Only P > Q ≥ R = S ≥ T keeps one direction throughout, giving P > T. Each other chain has a sign that reverses (R ≤ S, R < S, or R ≥ Q), which breaks the link.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-20", "question": "Rahul is 9th from the top and 38th from the bottom among the students who passed. Six students failed and three were absent. How many students were in the class?", "options": ["49", "46", "55", "52"], "answer": 2, "explanation": "Passed students = 9 + 38 − 1 = 46. Adding 6 who failed and 3 absent gives 46 + 6 + 3 = 55.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-21", "question": "Statements: X ≥ Y = Z, W ≤ Z. Conclusions: I. X > W  II. X = W", "options": ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither I nor II follows"], "answer": 2, "explanation": "X ≥ Y = Z ≥ W gives only X ≥ W. I (X > W) and II (X = W) together make up X ≥ W and cannot both hold, so either I or II follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-22", "question": "P scored more than Q. R scored less than S but more than P. T scored less than Q. Who scored the second lowest?", "options": ["T", "P", "Q", "R"], "answer": 2, "explanation": "S > R > P > Q > T, so the second lowest is Q.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-23", "question": "In a row of 45 children, Ira is 17th from the left and Om is 22nd from the right. How many children sit between them?", "options": ["4", "7", "6", "5"], "answer": 2, "explanation": "Om is 45 − 22 + 1 = 24th from the left. Children between seats 17 and 24 are 18 to 23: 6.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-24", "question": "Which pair of symbols, in order, should replace the two ? signs in L ? M ≥ N ? O so that both ‘L > O’ and ‘N ≥ O’ are definitely true?", "options": [">, ≥", "=, <", "≥, ≤", "<, ≥"], "answer": 0, "explanation": "L > M ≥ N ≥ O gives L > O and N ≥ O. With ≤ or < in the second place N ≥ O fails, and with < in the first place L > O fails.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-25", "question": "P @ Q means P is not smaller than Q; P # Q means P is neither greater than nor equal to Q; P $ Q means P is neither smaller than nor equal to Q; P % Q means P is not greater than Q; P & Q means P is neither smaller than nor greater than Q. Statements: D $ E, E @ F, F & G, H # G. Conclusions: I. D $ H  II. E $ H  III. F @ H", "options": ["Only I and II follow", "All I, II and III follow", "Only I follows", "Only II and III follow"], "answer": 1, "explanation": "Decoded: D > E ≥ F = G > H. So D > H (I), E > H (II) and F > H, which makes F ≥ H true (III). All three follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-26", "question": "Statements: A ≥ B = C < D ≤ E, F > C. Conclusions: I. A ≥ C  II. E > B  III. F > A", "options": ["Only I follows", "Only II and III follow", "Only I and II follow", "All I, II and III follow"], "answer": 2, "explanation": "A ≥ B = C gives I. E ≥ D > C = B gives II. F > C and A ≥ C both point away from C, so F versus A is unknown; III does not follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-27", "question": "In a row of 60 persons facing north, A is 18th from the left end and B is 27th from the right end. C sits exactly midway between A and B. What is C’s position from the left end?", "options": ["27th", "26th", "35th", "25th"], "answer": 1, "explanation": "B is 60 − 27 + 1 = 34th from the left. Midway between 18 and 34 is (18 + 34)/2 = 26, so C is 26th from the left.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-28", "question": "In a row, M is 12th from the left and N is 18th from the right. When they interchange places, M becomes 22nd from the left. How many persons are in the row, and how many sit between M and N?", "options": ["39; 9", "39; 10", "38; 9", "40; 10"], "answer": 0, "explanation": "N’s seat is 22nd from the left, so the total is 22 + 18 − 1 = 39. Between seats 12 and 22 are seats 13 to 21: 9 persons.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-29", "question": "A is taller than B but shorter than C. D is taller than C. E is shorter than B but taller than F. How many of these statements are definitely true? I. A is the third tallest. II. E is the second shortest. III. Exactly two persons are taller than A. IV. C is the tallest.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "The order is D > C > A > B > E > F. I, II and III are true; IV is false because D is taller than C.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-30", "question": "Statement: K ≤ L < M = N ≥ O > P. Conclusions: I. O < M  II. O = M  III. K < N", "options": ["Only III follows", "Either I or II follows", "Only III follows, and either I or II follows", "All I, II and III follow"], "answer": 2, "explanation": "M = N ≥ O means O ≤ M, so exactly one of O < M and O = M holds: either I or II. K ≤ L < M = N gives K < N, so III follows.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-31", "question": "Sunita is 11th from the top in a class. Gita is 8 ranks below Sunita and is 23rd from the bottom. How many students are in the class?", "options": ["41", "33", "40", "42"], "answer": 0, "explanation": "Gita is 11 + 8 = 19th from the top and 23rd from the bottom, so total = 19 + 23 − 1 = 41.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-32", "question": "In a row of girls, Neha is 9th from the left and Priya is 16th from the right. Neha moves 5 places to the right and Priya moves 4 places to the left; they now sit next to each other with Neha immediately to the left of Priya. How many girls are in the row?", "options": ["35", "30", "34", "33"], "answer": 2, "explanation": "Neha is now 14th from the left, so Priya is 15th from the left. Moving 4 places left makes Priya 16 + 4 = 20th from the right. Total = 15 + 20 − 1 = 34.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-33", "question": "P is older than Q but younger than R. S is younger than T but older than R. U is younger than Q. Who is fourth from the eldest, and how many are younger than that person?", "options": ["R; three", "P; three", "P; two", "Q; one"], "answer": 2, "explanation": "T > S > R > P > Q > U. Fourth from the eldest is P, and two persons (Q and U) are younger than P.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-34", "question": "Which of the following expressions makes both ‘M ≥ Q’ and ‘P > N’ definitely true?", "options": ["M ≥ N > O = P ≥ Q", "N < P ≤ O ≥ M ≤ Q", "P > N ≥ M = O ≥ Q", "Q ≤ O < M ≥ N > P"], "answer": 2, "explanation": "In P > N ≥ M = O ≥ Q, M = O ≥ Q gives M ≥ Q and P > N is stated. The second gives P < N, the third N > P, and the fourth M ≤ Q, so each fails one conclusion.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-35", "question": "Among six students, P scored more than Q and R. S scored less than R but more than T. U scored the highest, and Q scored more than R. How many of these statements are true? I. Q is fourth from the top. II. Exactly three students scored less than R. III. P scored the second highest. IV. T scored the lowest.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "U > P > Q > R > S > T. III and IV are true; Q is third (not fourth) from the top and only S and T scored less than R.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-36", "question": "P ★ Q means P ≥ Q; P ▲ Q means P > Q; P ● Q means P = Q; P ■ Q means P ≤ Q; P ◆ Q means P < Q. Statements: J ▲ K, K ● L, L ■ M, N ◆ L. Conclusions: I. J ▲ N  II. M ★ N  III. J ▲ M  IV. K ★ N", "options": ["Only I and II follow", "Only II and IV follow", "All I, II, III and IV follow", "Only I, II and IV follow"], "answer": 3, "explanation": "Decoded: J > K = L ≤ M and N < L. J > N (I), M ≥ L > N so M ≥ N (II), K = L > N so K ≥ N (IV). J and M both relate to L in opposite senses, so III is unknown.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-37", "question": "In a queue, A is 7th from the front and B is 11th from the back, with A ahead of B. C stands exactly midway between A and B, and 5 persons stand between A and C. How many persons are in the queue?", "options": ["29", "30", "28", "24"], "answer": 0, "explanation": "C is 7 + 6 = 13th from the front; being midway, C is 6 places from both, so B is 19th from the front. Total = 19 + 11 − 1 = 29.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-38", "question": "Among seven boxes, P is heavier than Q but lighter than R. S is lighter than both T and Q. R is lighter than U. V is the lightest, and T is heavier than U. Which box is exactly in the middle when they are arranged by weight?", "options": ["Q", "U", "R", "P"], "answer": 3, "explanation": "T > U > R > P > Q > S > V, so the fourth heaviest (the middle of seven) is P.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-39", "question": "Statements: G ≥ H, H < I, I ≤ J, K = H. Conclusions: I. K < J  II. G < I  III. G ≥ I", "options": ["Only I follows", "Either II or III follows", "All I, II and III follow", "Only I follows, and either II or III follows"], "answer": 3, "explanation": "J ≥ I > H = K gives K < J (I). G ≥ H and I > H leave G and I unrelated, but II and III together cover every case and exclude each other, so either II or III follows.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-40", "question": "In a row of boys, Arun is 11th from the left and Varun is 17th from the right. Exactly 4 boys sit between them. What are the maximum and minimum possible numbers of boys in the row?", "options": ["32 and 22", "32 and 23", "31 and 21", "33 and 22"], "answer": 0, "explanation": "If Varun is to Arun’s right he is 16th from the left: 16 + 17 − 1 = 32. If he is to Arun’s left he is 6th from the left: 6 + 17 − 1 = 22.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-41", "question": "If P < Q = R ≤ S, which of the following is definitely true?", "options": ["Q > S", "P < S", "P = R", "R > S"], "answer": 1, "explanation": "P < Q = R ≤ S gives P < S. Q and R are at most S, so Q > S and R > S are false, and P is strictly less than R.", "difficulty": "easy", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-42", "question": "A tree is 7th from either end of a row of trees. How many trees are there in the row?", "options": ["13", "14", "12", "15"], "answer": 0, "explanation": "Total = position from one end + position from the other end − 1 = 7 + 7 − 1 = 13.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-43", "question": "Statements: A > B, B > C. Conclusions: I. A > C  II. C < B", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "A > B > C gives A > C (I), and B > C is the same as C < B (II). Both follow.", "difficulty": "easy", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-44", "question": "If the digits of the number 73915 are arranged in ascending order, which digit will be in the middle?", "options": ["3", "7", "9", "5"], "answer": 3, "explanation": "Ascending order: 1, 3, 5, 7, 9. The middle (third) digit is 5.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-45", "question": "If A ≥ B and B ≥ A, which of the following is definitely true?", "options": ["A > B", "A = B", "A < B", "Nothing can be said"], "answer": 1, "explanation": "A cannot be greater than B (that would break B ≥ A) and cannot be less (that would break A ≥ B), so A = B.", "difficulty": "easy", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-46", "question": "Statements: A ≥ B > C, D ≤ C. Conclusions: I. A > D  II. B > D", "options": ["Only I follows", "Only II follows", "Neither I nor II follows", "Both I and II follow"], "answer": 3, "explanation": "Combined: A ≥ B > C ≥ D. A > D and B > D both hold because a strict '>' lies on each path.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-47", "question": "Statements: P < Q ≤ R, S > R. Conclusions: I. S > P  II. Q ≥ S", "options": ["Only I follows", "Only II follows", "Either I or II follows", "Both I and II follow"], "answer": 0, "explanation": "Combined: P < Q ≤ R < S, so S > P (I follows) and Q < S, which makes Q ≥ S false.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-48", "question": "Which word comes third when these words are arranged in dictionary order? Banana, Bandit, Banner, Bangle", "options": ["Bandit", "Banner", "Bangle", "Banana"], "answer": 2, "explanation": "All begin with 'ban'; compare the fourth letter: Banana (a), Bandit (d), Bangle (g), Banner (n). The third word is Bangle.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-49", "question": "In a row, Asha is 8th from the left end and Bina is 12th from the right end. Asha sits to the immediate left of Bina. How many persons are there in the row?", "options": ["19", "21", "20", "22"], "answer": 2, "explanation": "Bina is just right of Asha, so she is 9th from the left. Total = 9 + 12 − 1 = 20.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-50", "question": "If the digits of the number 482693 are arranged in ascending order from left to right, how many digits will remain in their original positions?", "options": ["1", "0", "2", "3"], "answer": 0, "explanation": "Original: 4 8 2 6 9 3; ascending: 2 3 4 6 8 9. Only the 6 (fourth place) stays where it was, so one digit.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-51", "question": "Among P, Q, R, S and T, each scored different marks. Q scored more than only T. R scored more than P but less than S. Who scored the third highest marks?", "options": ["R", "P", "Q", "S"], "answer": 1, "explanation": "Q is fourth and T fifth. The top three are S, R and P with S > R > P, so P is third.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-52", "question": "A $ B means A ≥ B; A # B means A < B; A @ B means A = B. Statements: X $ Y, Y @ Z, Z # W. Conclusions: I. X $ Z  II. W # Y", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Decoded: X ≥ Y = Z < W. X ≥ Z, so I follows. W > Z = Y, so W < Y is false and II does not follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-53", "question": "Statement: J ≥ K = L ≤ M. Conclusions: I. J = L  II. J > L", "options": ["Only I follows", "Either I or II follows", "Only II follows", "Neither I nor II follows"], "answer": 1, "explanation": "J ≥ K = L gives J ≥ L. Each of J = L and J > L alone is uncertain, but one of them must be true, so either I or II follows.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-54", "question": "A is taller than B and C. D is taller than A. E is shorter than C but taller than B. Who is the third tallest?", "options": ["A", "E", "B", "C"], "answer": 3, "explanation": "D > A, and A is taller than B and C; among the rest C > E > B. Order: D, A, C, E, B, so C is third.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-55", "question": "Statements: A > B ≥ C, C = D, E < D, F ≥ A. Conclusions: I. F > E  II. B > D  III. A > E", "options": ["Only I and II follow", "Only II and III follow", "All I, II and III follow", "Only I and III follow"], "answer": 3, "explanation": "Combined: F ≥ A > B ≥ C = D > E. F > E and A > E follow. B ≥ D allows B = D, so B > D is not certain.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-56", "question": "Which of the following expressions makes both 'A < D' and 'C ≥ E' definitely false?", "options": ["E ≥ C > A ≥ D", "D > B = A ≥ C < E", "E > C = A ≥ B ≥ D", "A ≥ B > D, C ≤ E"], "answer": 2, "explanation": "For both to be definitely false we need A ≥ D and C < E for certain. In E > C = A ≥ B ≥ D, A ≥ D and C < E. In the others C = E remains possible or A < D is actually true.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-57", "question": "Statements: K < L ≤ M = N, O > N, P ≤ K. Conclusions: I. O > P  II. M > P  III. L ≥ O", "options": ["Only I and II follow", "Only I follows", "All follow", "Only II and III follow"], "answer": 0, "explanation": "Combined: P ≤ K < L ≤ M = N < O. O > P and M > P follow; O is greater than L, so L ≥ O is false.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-58", "question": "In a class of 40 students, Pooja is 12th from the top and Rahul is 18th from the bottom. How many students rank between them?", "options": ["11", "9", "10", "12"], "answer": 2, "explanation": "Rahul's rank from the top = 40 − 18 + 1 = 23. Between ranks 12 and 23 are 23 − 12 − 1 = 10 students.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-59", "question": "In a row of 50 persons facing north, A is 15th from the left end. B is 6th to the right of A, and C is 4th to the left of B. What is C's position from the right end?", "options": ["33rd", "34th", "35th", "36th"], "answer": 1, "explanation": "B = 15 + 6 = 21st from the left; C = 21 − 4 = 17th. From the right: 50 − 17 + 1 = 34th.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-60", "question": "Arrange these words in dictionary order: 1. Diversion  2. Divide  3. Divine  4. Division  5. Diverge", "options": ["5-1-2-3-4", "1-5-2-3-4", "5-1-3-2-4", "2-3-5-1-4"], "answer": 0, "explanation": "After 'div', words with 'e' come before 'i': Diverge (g) before Diversion (s). Then Divide (d), Divine (n), Division (s). So 5-1-2-3-4.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-61", "question": "In the number 638271, each digit is increased by 1 and the new digits are arranged in descending order. Which digit is then third from the right?", "options": ["3", "7", "4", "8"], "answer": 2, "explanation": "Adding 1: 7, 4, 9, 3, 8, 2. Descending: 9, 8, 7, 4, 3, 2. From the right: 2, 3, 4, so the third from the right is 4.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-62", "question": "Among P, Q, R, S and T, each of a different weight, P is heavier than only two persons. R is heavier than P but lighter than T. Q is not the lightest. The heaviest weighs 80 kg and the second lightest weighs 45 kg. Who weighs 45 kg?", "options": ["S", "P", "R", "Q"], "answer": 3, "explanation": "P is third. R and T are above P with T heavier, so T is first (80 kg) and R second. Q and S are the bottom two and Q is not the lightest, so Q is second lightest, 45 kg.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-63", "question": "Statements: A ≥ B, B > C, C ≤ D, D = E. Conclusions: I. A > C  II. E ≥ C  III. B ≤ E  IV. B > E", "options": ["Only I and II follow", "Only I, II and III follow", "Only I and II follow, and either III or IV follows", "Only II follows, and either III or IV follows"], "answer": 2, "explanation": "A ≥ B > C gives A > C; E = D ≥ C gives E ≥ C. B and E are both above C with no direct link, so III and IV are each uncertain, but together they cover every case: either III or IV follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-64", "question": "P δ Q means P is not smaller than Q; P λ Q means P is neither greater nor smaller than Q; P μ Q means P is not greater than Q; P θ Q means P is smaller than Q. Statements: A θ B, B λ C, C δ D. Conclusions: I. A θ C  II. D μ B", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither follows"], "answer": 2, "explanation": "Decoded: A < B = C ≥ D. A < C, so I follows; D ≤ C = B, so D ≤ B and II follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-65", "question": "In a class, Ravi ranks 8th from the top and 17th from the bottom among the boys. The class has 4 more girls than boys, and Sita ranks 5th from the top among the girls. What is Sita's rank from the bottom among the girls?", "options": ["24th", "23rd", "25th", "20th"], "answer": 0, "explanation": "Boys = 8 + 17 − 1 = 24, so girls = 28. Sita from the bottom = 28 − 5 + 1 = 24th.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-66", "question": "A is taller than B but shorter than C. D is shorter than B. E is taller than C. F is shorter than D. How many persons are definitely shorter than A?", "options": ["2", "4", "3", "1"], "answer": 2, "explanation": "Chain: E > C > A > B > D > F. B, D and F are shorter than A: 3.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-67", "question": "If the letters of the word PLANET are arranged in alphabetical order, how many letters will remain in their original positions?", "options": ["1", "3", "0", "2"], "answer": 3, "explanation": "PLANET → A, E, L, N, P, T. Comparing P L A N E T with A E L N P T, N (4th) and T (6th) stay. So 2.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-68", "question": "Statements: P ≥ Q > R ≤ S < T, U = R. Conclusions: I. P > U  II. T > R  III. S ≥ U  IV. Q ≥ T", "options": ["Only I and II follow", "Only I, II and III follow", "All follow", "Only II, III and IV follow"], "answer": 1, "explanation": "P ≥ Q > R = U gives P > U. T > S ≥ R gives T > R. S ≥ R = U gives S ≥ U. Q and T both lie above R with no link between them, so IV is uncertain.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-69", "question": "P α Q means P ≥ Q; P β Q means P > Q; P γ Q means P = Q; P δ Q means P ≤ Q; P ε Q means P < Q. Statements: A α B, B γ C, C ε D, E δ C. Conclusions: I. A β E  II. A γ E  III. D β E", "options": ["Only III follows", "Only I and III follow", "III follows and either I or II follows", "Either I or II follows"], "answer": 2, "explanation": "Decoded: A ≥ B = C < D and E ≤ C. So A ≥ E, which means either A > E or A = E (either I or II). D > C ≥ E, so D > E and III follows.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-70", "question": "In which of these expressions is 'P > T' definitely true and 'Q ≥ T' definitely false?", "options": ["P > S ≥ T ≥ Q", "P ≥ R > T > S ≥ Q", "Q < S ≥ T < R = P", "T < R ≤ P, Q ≥ S > T"], "answer": 1, "explanation": "In P ≥ R > T > S ≥ Q, P > T and Q ≤ S < T, so Q < T for certain. In the first option Q = T is possible, in the third Q and T are unlinked, and in the fourth Q > T.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-71", "question": "Riya ranks 14th from the top and 27th from the bottom in her class. Later, 6 students ranked above her leave the class and 4 new students join, all ranked above her. What are her new ranks from the top and from the bottom?", "options": ["12th and 27th", "12th and 25th", "10th and 27th", "16th and 27th"], "answer": 0, "explanation": "The class had 14 + 27 − 1 = 40. From the top: 14 − 6 + 4 = 12th. Nobody below her changed, so she stays 27th from the bottom; check: 12 + 27 − 1 = 38 = 40 − 6 + 4.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-72", "question": "Among six boxes A to F, each of a different weight, A is heavier than D but lighter than B. C is heavier than only E. F is lighter than D. The second heaviest box weighs 52 kg and C weighs 31 kg. Which of these could be the weight of D?", "options": ["30 kg", "55 kg", "52 kg", "45 kg"], "answer": 3, "explanation": "E is lightest and C fifth; B > A > D > F fill the top four, so A (second heaviest) is 52 kg. D must be below 52 kg and above F, which is above C (31 kg). Only 45 kg fits.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-73", "question": "Statements: M > N ≥ O < P = Q, R ≤ O. How many of these conclusions definitely follow? I. M > R  II. P > R  III. N ≥ R  IV. Q ≥ N", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "M > N ≥ O ≥ R gives M > R and N ≥ R; P > O ≥ R gives P > R. Q and N both lie above O with no link, so IV is uncertain. Three follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-74", "question": "If these words are arranged in reverse dictionary order, which word comes second? Constant, Consider, Console, Consent, Consume", "options": ["Console", "Constant", "Consume", "Consider"], "answer": 1, "explanation": "All share 'cons'. Next letters: Consent (e), Consider (i), Console (o), Constant (t), Consume (u). Reverse order: Consume, Constant, Console, Consider, Consent, so Constant is second.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-75", "question": "In the number 9274638, the first and second digits are interchanged, then the third and fourth, then the fifth and sixth; the seventh digit stays. If the digits of the new number are then arranged in ascending order, how many digits remain in the same positions as in the new number?", "options": ["1", "3", "2", "0"], "answer": 2, "explanation": "After interchanging: 2 9 4 7 3 6 8. Ascending: 2 3 4 6 7 8 9. The 2 (first place) and the 4 (third place) stay: two digits.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-76", "question": "Statements: G > H ≥ I, J ≤ I, K < J. Conclusions: I. G > K  II. H > K  III. I = K  IV. I > K", "options": ["Only I and II follow", "I, II and IV follow", "I and II follow, and either III or IV follows", "Only IV follows"], "answer": 1, "explanation": "Combined: G > H ≥ I ≥ J > K. G > K, H > K and I > K all follow for certain, so IV follows and III is false. 'Either III or IV' is the trap: it applies only when neither is certain on its own.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-77", "question": "In a row, A is 10th from the left end and B is 15th from the right end. If A moves 4 places to the right, A becomes 7th to the left of B. How many persons are there in the row?", "options": ["34", "36", "33", "35"], "answer": 3, "explanation": "A's new position is 14th from the left, so B is 14 + 7 = 21st from the left. Total = 21 + 15 − 1 = 35.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-78", "question": "Statements: A > B, B ≥ C, D ≤ C, D > E, F = E. Conclusions: I. A > F  II. C > F  III. B ≥ D  IV. F < B", "options": ["Only I and II follow", "Only I, II and III follow", "Only III and IV follow", "All follow"], "answer": 3, "explanation": "Combined: A > B ≥ C ≥ D > E = F. Every conclusion has a strict '>' (or a valid ≥) on its path, so all four follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-79", "question": "Which symbols, in order, should replace the ? signs in 'J ? K ? L ? M' so that 'J ≥ M' is definitely true but 'J > M' is not definitely true?", "options": ["≥, =, ≥", "≥, >, =", "≤, =, ≥", "=, ≥, ≤"], "answer": 0, "explanation": "J ≥ K = L ≥ M gives J ≥ M, with J = M still possible, so J > M is not certain. In the second option J > M is certain; in the third and fourth J and M are not linked in one direction.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-80", "question": "Ankit scored more than Bimal but less than Chetan. Divya scored less than Bimal. Esha scored more than Chetan. Farah scored less than Chetan but more than Ankit. Who ranks third, and how many scored more than Ankit?", "options": ["F; two", "C; three", "F; three", "E; three"], "answer": 2, "explanation": "Order: Esha > Chetan > Farah > Ankit > Bimal > Divya. Farah is third, and three persons (Esha, Chetan, Farah) scored more than Ankit.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-81", "question": "In a queue, P is 14th from the front. Q stands 10 places behind P, and R stands exactly midway between P and Q. The last person in the queue stands 7 places behind Q. What is R's position from the back?", "options": ["12th", "14th", "13th", "11th"], "answer": 2, "explanation": "Q = 24th from the front, R = (14 + 24) ÷ 2 = 19th, and the last person is 24 + 7 = 31st, so the queue has 31. R from the back = 31 − 19 + 1 = 13th.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-82", "question": "P # Q means P is not greater than Q; P @ Q means P is not less than Q; P $ Q means P is greater than Q; P & Q means P is equal to Q; P % Q means P is less than Q. Statements: M @ N, N # O, O & P, Q % P. Conclusions: I. M $ Q  II. O $ Q  III. N % P  IV. N # P", "options": ["Only II follows", "Only II and IV follow", "Only I and II follow", "Only II, III and IV follow"], "answer": 1, "explanation": "Decoded: M ≥ N ≤ O = P > Q. O > Q (II) follows, and N ≤ P (IV) follows. N < P is not certain because N may equal P, and M and Q are not linked, so I and III do not follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-inequality-order-83", "question": "Twenty-five students stand in a row facing north. Mohan is 7th from the left end, Sohan is 3 places to the right of Mohan, and Rohan is 6th from the right end. If Mohan and Rohan interchange positions, where will Sohan be relative to Mohan?", "options": ["9th to the left of Mohan", "10th to the right of Mohan", "11th to the left of Mohan", "10th to the left of Mohan"], "answer": 3, "explanation": "Sohan = 10th from the left; Rohan = 25 − 6 + 1 = 20th. After the interchange Mohan is 20th, so Sohan (10th) is 10 places to his left.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-84", "question": "A is taller than B and C. D is shorter than B but taller than E. Which of the following must be true?", "options": ["A is taller than D", "C is taller than E", "B is the second tallest", "E is the shortest"], "answer": 0, "explanation": "A > B > D > E, so A is taller than D for certain. C is known only to be shorter than A, so its place relative to B, D and E is unknown, which leaves the other three options uncertain.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "reason-inequality-order-85", "question": "If X ≥ Y < Z, Z ≤ W = V and Y = U, which of the following is definitely true?", "options": ["X > U", "Z ≥ X", "U < V", "W > X"], "answer": 2, "explanation": "U = Y < Z ≤ W = V, so U < V. X ≥ Y = U allows X = U, and X has no link with Z, W or V.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-86","question":"Statements: B ≤ J ≤ G ≤ F. Conclusions: I. G ≥ B II. F ≤ B","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows"],"answer":0,"explanation":"I (G ≥ B): G ≥ J ≥ B gives G ≥ B, so it follows. II (F ≤ B): F ≥ G ≥ J ≥ B gives F ≥ B, which does not guarantee F ≤ B; it does not follow on its own.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-87","question":"Statements: P ≤ C = H ≥ G. Conclusions: I. G ≤ P II. G ≤ C","options":["Neither conclusion I nor II follows","Only conclusion II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":1,"explanation":"I (G ≤ P): in the chain G ≤ H = C ≥ P the signs open in opposite directions, so no definite relation can be drawn between G and P; it does not follow. II (G ≤ C): G ≤ H = C gives G ≤ C, so it follows.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-88","question":"Statements: L > H = Z > S. Conclusions: I. L ≥ Z II. S < L","options":["Only conclusion II follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":2,"explanation":"I (L ≥ Z): L > H = Z gives L > Z, so it follows. II (S < L): S < Z = H < L gives S < L, so it follows.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-89","question":"Statements: W = F ≥ L ≤ X. Conclusions: I. W ≥ L II. W < X","options":["Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows","Only conclusion I follows"],"answer":3,"explanation":"I (W ≥ L): W = F ≥ L gives W ≥ L, so it follows. II (W < X): in the chain W = F ≥ L ≤ X the signs open in opposite directions, so no definite relation can be drawn between W and X; it does not follow.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-90","question":"Statements: G ≥ S ≥ B > M. Conclusions: I. G > M II. G ≥ B","options":["Both conclusions I and II follow","Neither conclusion I nor II follows","Only conclusion I follows","Either conclusion I or II follows"],"answer":0,"explanation":"I (G > M): G ≥ S ≥ B > M gives G > M, so it follows. II (G ≥ B): G ≥ S ≥ B gives G ≥ B, so it follows.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-91","question":"Statements: L = O ≥ M < U. Conclusions: I. U ≤ O II. M ≤ L","options":["Neither conclusion I nor II follows","Only conclusion II follows","Either conclusion I or II follows","Only conclusion I follows"],"answer":1,"explanation":"I (U ≤ O): in the chain U > M ≤ O the signs open in opposite directions, so no definite relation can be drawn between U and O; it does not follow. II (M ≤ L): M ≤ O = L gives M ≤ L, so it follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-92","question":"Statements: G < Z ≤ A = Y. Conclusions: I. Y > Z II. Y = Z","options":["Only conclusion II follows","Only conclusion I follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":2,"explanation":"I (Y > Z): Y = A ≥ Z gives Y ≥ Z, which does not guarantee Y > Z; it does not follow on its own. II (Y = Z): Y = A ≥ Z gives Y ≥ Z, which does not guarantee Y = Z; it does not follow on its own. Together, the statements give Y ≥ Z, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-93","question":"Statements: M ≤ E ≥ N ≥ O. Conclusions: I. N < M II. M > O","options":["Either conclusion I or II follows","Only conclusion I follows","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I (N < M): in the chain N ≤ E ≥ M the signs open in opposite directions, so no definite relation can be drawn between N and M; it does not follow. II (M > O): in the chain M ≤ E ≥ N ≥ O the signs open in opposite directions, so no definite relation can be drawn between M and O; it does not follow.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-94","question":"Statements: D < Y < R = H. Conclusions: I. R ≥ D II. D < H","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":0,"explanation":"I (R ≥ D): R > Y > D gives R > D, so it follows. II (D < H): D < Y < R = H gives D < H, so it follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-95","question":"Statements: N ≥ E = R > K. Conclusions: I. K < E II. R ≥ N","options":["Only conclusion II follows","Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows"],"answer":1,"explanation":"I (K < E): K < R = E gives K < E, so it follows. II (R ≥ N): R = E ≤ N gives R ≤ N, which does not guarantee R ≥ N; it does not follow on its own.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-96","question":"Statements: O = J ≤ C; K ≤ J. Conclusions: I. C = K II. C > K","options":["Only conclusion II follows","Only conclusion I follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":2,"explanation":"I (C = K): C ≥ J ≥ K gives C ≥ K, which does not guarantee C = K; it does not follow on its own. II (C > K): C ≥ J ≥ K gives C ≥ K, which does not guarantee C > K; it does not follow on its own. Together, the statements give C ≥ K, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-97","question":"Statements: U ≤ P ≥ B = T; X ≤ C < U. Conclusions: I. U ≥ X II. T ≥ U","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":3,"explanation":"I (U ≥ X): U > C ≥ X gives U > X, so it follows. II (T ≥ U): in the chain T = B ≤ P ≥ U the signs open in opposite directions, so no definite relation can be drawn between T and U; it does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-98","question":"Statements: F = M ≤ X > R; E = O < M. Conclusions: I. R ≤ F II. X ≥ E","options":["Only conclusion II follows","Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":0,"explanation":"I (R ≤ F): in the chain R < X ≥ M = F the signs open in opposite directions, so no definite relation can be drawn between R and F; it does not follow. II (X ≥ E): X ≥ M > O = E gives X > E, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-99","question":"Statements: E ≤ O < A ≥ H; O ≤ Q ≤ C. Conclusions: I. O < C II. O = C","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows","Only conclusion II follows"],"answer":1,"explanation":"I (O < C): O ≤ Q ≤ C gives O ≤ C, which does not guarantee O < C; it does not follow on its own. II (O = C): O ≤ Q ≤ C gives O ≤ C, which does not guarantee O = C; it does not follow on its own. Together, the statements give O ≤ C, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-100","question":"Statements: T ≤ H > K > P; H < F ≥ R. Conclusions: I. P = R II. T ≤ K","options":["Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows","Either conclusion I or II follows"],"answer":2,"explanation":"I (P = R): in the chain P < K < H < F ≥ R the signs open in opposite directions, so no definite relation can be drawn between P and R; it does not follow. II (T ≤ K): in the chain T ≤ H > K the signs open in opposite directions, so no definite relation can be drawn between T and K; it does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-101","question":"Statements: O < Q < U < Z; U ≤ S ≤ D. Conclusions: I. U ≥ O II. Q ≤ Z","options":["Only conclusion II follows","Neither conclusion I nor II follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":3,"explanation":"I (U ≥ O): U > Q > O gives U > O, so it follows. II (Q ≤ Z): Q < U < Z gives Q < Z, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-102","question":"Statements: V < O ≥ C ≥ D = N; N = B. Conclusions: I. D = O II. D < O","options":["Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":0,"explanation":"I (D = O): D ≤ C ≤ O gives D ≤ O, which does not guarantee D = O; it does not follow on its own. II (D < O): D ≤ C ≤ O gives D ≤ O, which does not guarantee D < O; it does not follow on its own. Together, the statements give D ≤ O, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-103","question":"Statements: F > J = N ≤ C > A; P ≥ C. Conclusions: I. F > A II. A ≤ P","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Either conclusion I or II follows"],"answer":1,"explanation":"I (F > A): in the chain F > J = N ≤ C > A the signs open in opposite directions, so no definite relation can be drawn between F and A; it does not follow. II (A ≤ P): A < C ≤ P gives A < P, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-104","question":"Statements: R > E ≥ S < H ≤ M; S > Q ≤ N. Conclusions: I. H ≥ E II. H = R","options":["Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":2,"explanation":"I (H ≥ E): in the chain H > S ≤ E the signs open in opposite directions, so no definite relation can be drawn between H and E; it does not follow. II (H = R): in the chain H > S ≤ E < R the signs open in opposite directions, so no definite relation can be drawn between H and R; it does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-105","question":"Statements: G ≥ B ≥ Q = R ≤ W; B ≤ Y > X. Conclusions: I. B > R II. B = R","options":["Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows"],"answer":3,"explanation":"I (B > R): B ≥ Q = R gives B ≥ R, which does not guarantee B > R; it does not follow on its own. II (B = R): B ≥ Q = R gives B ≥ R, which does not guarantee B = R; it does not follow on its own. Together, the statements give B ≥ R, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-106","question":"Statements: T > A = Z ≥ Q ≤ B; N ≥ S ≥ B. Conclusions: I. T > Q II. Q ≥ A","options":["Only conclusion I follows","Either conclusion I or II follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":0,"explanation":"I (T > Q): T > A = Z ≥ Q gives T > Q, so it follows. II (Q ≥ A): Q ≤ Z = A gives Q ≤ A, which does not guarantee Q ≥ A; it does not follow on its own.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-107","question":"Statements: Y ≥ L ≤ A > B < H; M < S ≤ B. Conclusions: I. L = M II. B = L","options":["Either conclusion I or II follows","Neither conclusion I nor II follows","Only conclusion II follows","Only conclusion I follows"],"answer":1,"explanation":"I (L = M): in the chain L ≤ A > B ≥ S > M the signs open in opposite directions, so no definite relation can be drawn between L and M; it does not follow. II (B = L): in the chain B < A ≥ L the signs open in opposite directions, so no definite relation can be drawn between B and L; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-108","question":"Statements: M = L > E > Q = D; O ≥ A ≤ E. Conclusions: I. L > Q II. M ≥ Q","options":["Only conclusion II follows","Either conclusion I or II follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":2,"explanation":"I (L > Q): L > E > Q gives L > Q, so it follows. II (M ≥ Q): M = L > E > Q gives M > Q, so it follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-109","question":"Statements: R ≤ K ≥ J ≤ B < U; K ≥ W > O. Conclusions: I. B = K II. J ≤ U","options":["Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":3,"explanation":"I (B = K): in the chain B ≥ J ≤ K the signs open in opposite directions, so no definite relation can be drawn between B and K; it does not follow. II (J ≤ U): J ≤ B < U gives J < U, so it follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-110","question":"Statements: S > B ≤ J ≥ O; U < S. Conclusions: I. U ≥ J II. S ≤ J","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows"],"answer":0,"explanation":"I (U ≥ J): in the chain U < S > B ≤ J the signs open in opposite directions, so no definite relation can be drawn between U and J; it does not follow. II (S ≤ J): in the chain S > B ≤ J the signs open in opposite directions, so no definite relation can be drawn between S and J; it does not follow.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-111","question":"Statements: S < L ≤ U > V; S ≤ R. Conclusions: I. U ≥ R II. S < U","options":["Neither conclusion I nor II follows","Only conclusion II follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":1,"explanation":"I (U ≥ R): in the chain U ≥ L > S ≤ R the signs open in opposite directions, so no definite relation can be drawn between U and R; it does not follow. II (S < U): S < L ≤ U gives S < U, so it follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-112","question":"Statements: N ≥ B ≥ A ≥ Y; H < N. Conclusions: I. N ≥ Y II. Y ≤ B","options":["Only conclusion II follows","Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":2,"explanation":"I (N ≥ Y): N ≥ B ≥ A ≥ Y gives N ≥ Y, so it follows. II (Y ≤ B): Y ≤ A ≤ B gives Y ≤ B, so it follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-113","question":"Statements: N = D ≤ S ≥ B > R; Q < R. Conclusions: I. R ≤ S II. R < D","options":["Both conclusions I and II follow","Neither conclusion I nor II follows","Either conclusion I or II follows","Only conclusion I follows"],"answer":3,"explanation":"I (R ≤ S): R < B ≤ S gives R < S, so it follows. II (R < D): in the chain R < B ≤ S ≥ D the signs open in opposite directions, so no definite relation can be drawn between R and D; it does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-114","question":"Statements: V = A ≤ K ≥ H ≥ N; S ≤ O > V. Conclusions: I. K ≥ V II. A < O","options":["Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows","Either conclusion I or II follows"],"answer":0,"explanation":"I (K ≥ V): K ≥ A = V gives K ≥ V, so it follows. II (A < O): A = V < O gives A < O, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-115","question":"Statements: G ≤ U ≥ E ≥ S = Q = J; R > G. Conclusions: I. U = S II. U > S","options":["Only conclusion I follows","Either conclusion I or II follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":1,"explanation":"I (U = S): U ≥ E ≥ S gives U ≥ S, which does not guarantee U = S; it does not follow on its own. II (U > S): U ≥ E ≥ S gives U ≥ S, which does not guarantee U > S; it does not follow on its own. Together, the statements give U ≥ S, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-116","question":"Statements: G ≥ K > X > L ≥ T < B; A ≤ D = K. Conclusions: I. T < G II. G < B","options":["Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":2,"explanation":"I (T < G): T ≤ L < X < K ≤ G gives T < G, so it follows. II (G < B): in the chain G ≥ K > X > L ≥ T < B the signs open in opposite directions, so no definite relation can be drawn between G and B; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-117","question":"Statements: U ≤ R > W ≥ M ≤ P = V; M = N. Conclusions: I. V ≥ R II. R = P","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I (V ≥ R): in the chain V = P ≥ M ≤ W < R the signs open in opposite directions, so no definite relation can be drawn between V and R; it does not follow. II (R = P): in the chain R > W ≥ M ≤ P the signs open in opposite directions, so no definite relation can be drawn between R and P; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-118","question":"In the following question, 'P # Q' means 'P is not smaller than Q'; 'P © Q' means 'P is neither greater than nor equal to Q'; 'P ★ Q' means 'P is neither smaller than nor equal to Q'; 'P & Q' means 'P is neither smaller than nor greater than Q'; 'P $ Q' means 'P is not greater than Q'. Statements: T # P, P $ V, V & U. Conclusions: I. P $ U II. T & V","options":["Only conclusion I follows","Only conclusion II follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":0,"explanation":"Decoding, the statements are T ≥ P, P ≤ V, V = U; the conclusions are I. P ≤ U and II. T = V. I (P ≤ U): P ≤ V = U gives P ≤ U, so it follows. II (T = V): in the chain T ≥ P ≤ V the signs open in opposite directions, so no definite relation can be drawn between T and V; it does not follow.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-119","question":"In the following question, 'P & Q' means 'P is neither smaller than nor greater than Q'; 'P % Q' means 'P is neither smaller than nor equal to Q'; 'P ★ Q' means 'P is not smaller than Q'; 'P # Q' means 'P is not greater than Q'; 'P @ Q' means 'P is neither greater than nor equal to Q'. Statements: C & Z, Z & X, X ★ O, L & O. Conclusions: I. O & Z II. O @ Z","options":["Neither conclusion I nor II follows","Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":1,"explanation":"Decoding, the statements are C = Z, Z = X, X ≥ O, L = O; the conclusions are I. O = Z and II. O < Z. I (O = Z): O ≤ X = Z gives O ≤ Z, which does not guarantee O = Z; it does not follow on its own. II (O < Z): O ≤ X = Z gives O ≤ Z, which does not guarantee O < Z; it does not follow on its own. Together, the statements give O ≤ Z, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-120","question":"In the following question, 'P @ Q' means 'P is not greater than Q'; 'P ★ Q' means 'P is not smaller than Q'; 'P & Q' means 'P is neither smaller than nor equal to Q'; 'P $ Q' means 'P is neither greater than nor equal to Q'; 'P # Q' means 'P is neither smaller than nor greater than Q'. Statements: K $ U, U & L, L $ P, L # W. Conclusions: I. P $ U II. W $ U","options":["Either conclusion I or II follows","Neither conclusion I nor II follows","Only conclusion II follows","Only conclusion I follows"],"answer":2,"explanation":"Decoding, the statements are K < U, U > L, L < P, L = W; the conclusions are I. P < U and II. W < U. I (P < U): in the chain P > L < U the signs open in opposite directions, so no definite relation can be drawn between P and U; it does not follow. II (W < U): W = L < U gives W < U, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-121","question":"In the following question, 'P # Q' means 'P is neither smaller than nor equal to Q'; 'P % Q' means 'P is neither greater than nor equal to Q'; 'P @ Q' means 'P is not greater than Q'; 'P ★ Q' means 'P is not smaller than Q'; 'P © Q' means 'P is neither smaller than nor greater than Q'. Statements: Y ★ S, S ★ B, B © L, Y % H. Conclusions: I. Y © L II. L % S","options":["Either conclusion I or II follows","Only conclusion II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"Decoding, the statements are Y ≥ S, S ≥ B, B = L, Y < H; the conclusions are I. Y = L and II. L < S. I (Y = L): Y ≥ S ≥ B = L gives Y ≥ L, which does not guarantee Y = L; it does not follow on its own. II (L < S): L = B ≤ S gives L ≤ S, which does not guarantee L < S; it does not follow on its own.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-122","question":"In the following question, 'P @ Q' means 'P is neither greater than nor equal to Q'; 'P & Q' means 'P is neither smaller than nor equal to Q'; 'P $ Q' means 'P is not greater than Q'; 'P % Q' means 'P is neither smaller than nor greater than Q'; 'P # Q' means 'P is not smaller than Q'. Statements: C % W, W $ H, H & F, Q $ W. Conclusions: I. Q $ H II. H # C","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":0,"explanation":"Decoding, the statements are C = W, W ≤ H, H > F, Q ≤ W; the conclusions are I. Q ≤ H and II. H ≥ C. I (Q ≤ H): Q ≤ W ≤ H gives Q ≤ H, so it follows. II (H ≥ C): H ≥ W = C gives H ≥ C, so it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-123","question":"In the following question, 'P % Q' means 'P is neither greater than nor equal to Q'; 'P & Q' means 'P is not smaller than Q'; 'P # Q' means 'P is not greater than Q'; 'P @ Q' means 'P is neither smaller than nor greater than Q'; 'P $ Q' means 'P is neither smaller than nor equal to Q'. Statements: X $ V, V @ K, K & D, D # S, O & V. Conclusions: I. O @ D II. O $ D","options":["Neither conclusion I nor II follows","Either conclusion I or II follows","Only conclusion II follows","Only conclusion I follows"],"answer":1,"explanation":"Decoding, the statements are X > V, V = K, K ≥ D, D ≤ S, O ≥ V; the conclusions are I. O = D and II. O > D. I (O = D): O ≥ V = K ≥ D gives O ≥ D, which does not guarantee O = D; it does not follow on its own. II (O > D): O ≥ V = K ≥ D gives O ≥ D, which does not guarantee O > D; it does not follow on its own. Together, the statements give O ≥ D, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-124","question":"In the following question, 'P # Q' means 'P is neither smaller than nor equal to Q'; 'P $ Q' means 'P is not smaller than Q'; 'P @ Q' means 'P is neither smaller than nor greater than Q'; 'P % Q' means 'P is neither greater than nor equal to Q'; 'P © Q' means 'P is not greater than Q'. Statements: B # Q, Q # N, N % D, D % O, M © N. Conclusions: I. B $ N II. D # B","options":["Neither conclusion I nor II follows","Only conclusion II follows","Only conclusion I follows","Either conclusion I or II follows"],"answer":2,"explanation":"Decoding, the statements are B > Q, Q > N, N < D, D < O, M ≤ N; the conclusions are I. B ≥ N and II. D > B. I (B ≥ N): B > Q > N gives B > N, so it follows. II (D > B): in the chain D > N < Q < B the signs open in opposite directions, so no definite relation can be drawn between D and B; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-125","question":"In the following question, 'P © Q' means 'P is neither smaller than nor greater than Q'; 'P $ Q' means 'P is neither greater than nor equal to Q'; 'P ★ Q' means 'P is not smaller than Q'; 'P # Q' means 'P is neither smaller than nor equal to Q'; 'P % Q' means 'P is not greater than Q'. Statements: Y ★ D, D % H, H © X, X © L, H © Q. Conclusions: I. Y # H II. X # Y","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"Decoding, the statements are Y ≥ D, D ≤ H, H = X, X = L, H = Q; the conclusions are I. Y > H and II. X > Y. I (Y > H): in the chain Y ≥ D ≤ H the signs open in opposite directions, so no definite relation can be drawn between Y and H; it does not follow. II (X > Y): in the chain X = H ≥ D ≤ Y the signs open in opposite directions, so no definite relation can be drawn between X and Y; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-126","question":"In the following question, 'P ★ Q' means 'P is neither smaller than nor greater than Q'; 'P & Q' means 'P is not greater than Q'; 'P $ Q' means 'P is neither greater than nor equal to Q'; 'P # Q' means 'P is not smaller than Q'; 'P % Q' means 'P is neither smaller than nor equal to Q'. Statements: X & R, R % L, L % D, X # N, N % K. Conclusions: I. D & X II. R % D","options":["Only conclusion II follows","Both conclusions I and II follow","Neither conclusion I nor II follows","Either conclusion I or II follows"],"answer":0,"explanation":"Decoding, the statements are X ≤ R, R > L, L > D, X ≥ N, N > K; the conclusions are I. D ≤ X and II. R > D. I (D ≤ X): in the chain D < L < R ≥ X the signs open in opposite directions, so no definite relation can be drawn between D and X; it does not follow. II (R > D): R > L > D gives R > D, so it follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-127","question":"In the following question, 'P # Q' means 'P is not greater than Q'; 'P $ Q' means 'P is neither smaller than nor greater than Q'; 'P & Q' means 'P is neither greater than nor equal to Q'; 'P ★ Q' means 'P is not smaller than Q'; 'P % Q' means 'P is neither smaller than nor equal to Q'. Statements: E & V, V # A, A & K, M & G, G # A. Conclusions: I. K ★ E II. G # K","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows"],"answer":1,"explanation":"Decoding, the statements are E < V, V ≤ A, A < K, M < G, G ≤ A; the conclusions are I. K ≥ E and II. G ≤ K. I (K ≥ E): K > A ≥ V > E gives K > E, so it follows. II (G ≤ K): G ≤ A < K gives G < K, so it follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-128","question":"In the following question, 'P © Q' means 'P is neither smaller than nor equal to Q'; 'P ★ Q' means 'P is neither greater than nor equal to Q'; 'P # Q' means 'P is not smaller than Q'; 'P & Q' means 'P is not greater than Q'; 'P $ Q' means 'P is neither smaller than nor greater than Q'. Statements: B $ D, D & F, F © H, F © S, S ★ T. Conclusions: I. B ★ F II. B $ F","options":["Only conclusion II follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows"],"answer":2,"explanation":"Decoding, the statements are B = D, D ≤ F, F > H, F > S, S < T; the conclusions are I. B < F and II. B = F. I (B < F): B = D ≤ F gives B ≤ F, which does not guarantee B < F; it does not follow on its own. II (B = F): B = D ≤ F gives B ≤ F, which does not guarantee B = F; it does not follow on its own. Together, the statements give B ≤ F, so the two conclusions cover every possibility between them: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-129","question":"In the following question, 'P & Q' means 'P is neither greater than nor equal to Q'; 'P $ Q' means 'P is neither smaller than nor greater than Q'; 'P % Q' means 'P is neither smaller than nor equal to Q'; 'P @ Q' means 'P is not greater than Q'; 'P # Q' means 'P is not smaller than Q'. Statements: J # E, E % X, X @ P, P % W, R @ M, M @ W. Conclusions: I. W % R II. M $ J","options":["Both conclusions I and II follow","Only conclusion II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"Decoding, the statements are J ≥ E, E > X, X ≤ P, P > W, R ≤ M, M ≤ W; the conclusions are I. W > R and II. M = J. I (W > R): W ≥ M ≥ R gives W ≥ R, which does not guarantee W > R; it does not follow on its own. II (M = J): in the chain M ≤ W < P ≥ X < E ≤ J the signs open in opposite directions, so no definite relation can be drawn between M and J; it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-130","question":"Statements: Y ≥ C ≥ D = J = L; C > F. Which of the following conclusions definitely follow? I. D < Y II. J ≤ C III. F < D","options":["Only II follows","Only I and II follow","All follow","Only III follows"],"answer":0,"explanation":"I (D < Y): D ≤ C ≤ Y gives D ≤ Y, which does not guarantee D < Y; it does not follow on its own. II (J ≤ C): J = D ≤ C gives J ≤ C, so it follows. III (F < D): in the chain F < C ≥ D the signs open in opposite directions, so no definite relation can be drawn between F and D; it does not follow. Hence the answer is 'Only II follows'.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-131","question":"Statements: M ≥ K ≤ J ≤ L; K = Z = F. Which of the following conclusions definitely follow? I. L ≤ K II. M ≤ Z III. F ≤ L","options":["Only I and III follow","Only III follows","Only II follows","Only I and II follow"],"answer":1,"explanation":"I (L ≤ K): L ≥ J ≥ K gives L ≥ K, which does not guarantee L ≤ K; it does not follow on its own. II (M ≤ Z): M ≥ K = Z gives M ≥ Z, which does not guarantee M ≤ Z; it does not follow on its own. III (F ≤ L): F = Z = K ≤ J ≤ L gives F ≤ L, so it follows. Hence the answer is 'Only III follows'.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-132","question":"Statements: P > A ≥ G < D < E; E < U < S. Which of the following conclusions definitely follow? I. E > A II. P ≤ D III. S ≥ E","options":["Only II follows","Only I follows","Only III follows","Only I and II follow"],"answer":2,"explanation":"I (E > A): in the chain E > D > G ≤ A the signs open in opposite directions, so no definite relation can be drawn between E and A; it does not follow. II (P ≤ D): in the chain P > A ≥ G < D the signs open in opposite directions, so no definite relation can be drawn between P and D; it does not follow. III (S ≥ E): S > U > E gives S > E, so it follows. Hence the answer is 'Only III follows'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-133","question":"Statements: J < R > A = U ≥ E; H > G > A. Which of the following conclusions definitely follow? I. J > H II. R ≥ G III. E < H IV. A ≤ H","options":["Only II and III follow","Only I and II follow","Only I and III follow","Only III and IV follow"],"answer":3,"explanation":"I (J > H): in the chain J < R > A < G < H the signs open in opposite directions, so no definite relation can be drawn between J and H; it does not follow. II (R ≥ G): in the chain R > A < G the signs open in opposite directions, so no definite relation can be drawn between R and G; it does not follow. III (E < H): E ≤ U = A < G < H gives E < H, so it follows. IV (A ≤ H): A < G < H gives A < H, so it follows. Hence the answer is 'Only III and IV follow'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-134","question":"Statements: S ≥ R ≤ O < Y ≥ H > F; T ≥ Y. Which of the following conclusions definitely follow? I. O < T II. T ≤ S III. H ≤ R IV. H ≤ T","options":["Only I and IV follow","Only III and IV follow","Only II and III follow","Only I and III follow"],"answer":0,"explanation":"I (O < T): O < Y ≤ T gives O < T, so it follows. II (T ≤ S): in the chain T ≥ Y > O ≥ R ≤ S the signs open in opposite directions, so no definite relation can be drawn between T and S; it does not follow. III (H ≤ R): in the chain H ≤ Y > O ≥ R the signs open in opposite directions, so no definite relation can be drawn between H and R; it does not follow. IV (H ≤ T): H ≤ Y ≤ T gives H ≤ T, so it follows. Hence the answer is 'Only I and IV follow'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-135","question":"Statements: O = X = T < M > Y; F ≥ E < X. Which of the following conclusions definitely follow? I. X ≥ Y II. Y > E III. F < Y IV. X ≤ M","options":["Only I and IV follow","Only IV follows","Only III follows","Only I and II follow"],"answer":1,"explanation":"I (X ≥ Y): in the chain X = T < M > Y the signs open in opposite directions, so no definite relation can be drawn between X and Y; it does not follow. II (Y > E): in the chain Y < M > T = X > E the signs open in opposite directions, so no definite relation can be drawn between Y and E; it does not follow. III (F < Y): in the chain F ≥ E < X = T < M > Y the signs open in opposite directions, so no definite relation can be drawn between F and Y; it does not follow. IV (X ≤ M): X = T < M gives X < M, so it follows. Hence the answer is 'Only IV follows'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-136","question":"Statements: L > D > M ≤ G ≤ R; Z = L. Which of the following conclusions definitely follow? I. D ≤ Z II. R < L III. D ≤ G","options":["All follow","Only I and II follow","Only I follows","Only II follows"],"answer":2,"explanation":"I (D ≤ Z): D < L = Z gives D < Z, so it follows. II (R < L): in the chain R ≥ G ≥ M < D < L the signs open in opposite directions, so no definite relation can be drawn between R and L; it does not follow. III (D ≤ G): in the chain D > M ≤ G the signs open in opposite directions, so no definite relation can be drawn between D and G; it does not follow. Hence the answer is 'Only I follows'.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-137","question":"Statements: G < D ≤ B ≤ K < X ≥ M; K > C > N. Which of the following conclusions definitely follow? I. M ≥ C II. M > D III. B ≤ X IV. C > B","options":["Only I follows","Only II follows","Only I and II follow","Only III follows"],"answer":3,"explanation":"I (M ≥ C): in the chain M ≤ X > K > C the signs open in opposite directions, so no definite relation can be drawn between M and C; it does not follow. II (M > D): in the chain M ≤ X > K ≥ B ≥ D the signs open in opposite directions, so no definite relation can be drawn between M and D; it does not follow. III (B ≤ X): B ≤ K < X gives B < X, so it follows. IV (C > B): in the chain C < K ≥ B the signs open in opposite directions, so no definite relation can be drawn between C and B; it does not follow. Hence the answer is 'Only III follows'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-138","question":"In which of the following expressions is 'K > A' definitely true?","options":["A < J ≤ W ≤ K ≤ D","K = D < W ≤ J < A","J = A < D < W ≥ K","J < A = D ≥ W = K"],"answer":0,"explanation":"In A < J ≤ W ≤ K ≤ D, the path K ≥ W ≥ J > A gives K > A, so K > A is definitely true. In J < A = D ≥ W = K, K = W ≤ D = A gives only K ≤ A, which does not make it definite. In K = D < W ≤ J < A, K = D < W ≤ J < A gives only K < A, which does not make it definite. In J = A < D < W ≥ K, K ≤ W > D > A has opposite signs, which does not make it definite.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-139","question":"In which of the following expressions is 'J ≤ G' definitely true?","options":["J > F ≥ H ≥ G = S","G = H ≥ F ≥ J < S","J < H > F ≥ S = G","J = F < H ≥ S < G"],"answer":1,"explanation":"In G = H ≥ F ≥ J < S, the path J ≤ F ≤ H = G gives J ≤ G, so J ≤ G is definitely true. In J = F < H ≥ S < G, J = F < H ≥ S < G has opposite signs, which does not make it definite. In J < H > F ≥ S = G, J < H > F ≥ S = G has opposite signs, which does not make it definite. In J > F ≥ H ≥ G = S, J > F ≥ H ≥ G gives only J > G, which does not make it definite.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-140","question":"In which of the following expressions is 'C < N' definitely true?","options":["G > N ≤ F = L ≤ C","N < L > G < C ≥ F","F = C < L = G = N","G ≤ C ≤ F ≥ N = L"],"answer":2,"explanation":"In F = C < L = G = N, the path C < L = G = N gives C < N, so C < N is definitely true. In G ≤ C ≤ F ≥ N = L, C ≤ F ≥ N has opposite signs, which does not make it definite. In N < L > G < C ≥ F, C > G < L > N has opposite signs, which does not make it definite. In G > N ≤ F = L ≤ C, C ≥ L = F ≥ N gives only C ≥ N, which does not make it definite.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-141","question":"In which of the following expressions is 'Y ≥ W' definitely true?","options":["F > H = W ≥ B ≥ Y","F < Y ≤ B = H < W","Y < F ≥ B = W ≥ H","F > W = B ≤ Y ≤ H"],"answer":3,"explanation":"In F > W = B ≤ Y ≤ H, the path Y ≥ B = W gives Y ≥ W, so Y ≥ W is definitely true. In F > H = W ≥ B ≥ Y, Y ≤ B ≤ W gives only Y ≤ W, which does not make it definite. In Y < F ≥ B = W ≥ H, Y < F ≥ B = W has opposite signs, which does not make it definite. In F < Y ≤ B = H < W, Y ≤ B = H < W gives only Y < W, which does not make it definite.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-142","question":"In which of the following expressions is 'E > N' definitely true?","options":["X = E = F = R > N","F > N < X ≥ E = R","X ≤ R ≤ N > F = E","N < F ≥ R < E < X"],"answer":0,"explanation":"In X = E = F = R > N, the path E = F = R > N gives E > N, so E > N is definitely true. In F > N < X ≥ E = R, E ≤ X > N has opposite signs, which does not make it definite. In X ≤ R ≤ N > F = E, E = F < N gives only E < N, which does not make it definite. In N < F ≥ R < E < X, E > R ≤ F > N has opposite signs, which does not make it definite.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-143","question":"In which of the following expressions is 'Z < O' definitely true?","options":["Z = T ≥ H ≥ Q = O","Q > Z ≤ H < O < T","O < H > Z ≥ Q > T","Z < Q > T ≥ H = O"],"answer":1,"explanation":"In Q > Z ≤ H < O < T, the path Z ≤ H < O gives Z < O, so Z < O is definitely true. In Z < Q > T ≥ H = O, Z < Q > T ≥ H = O has opposite signs, which does not make it definite. In Z = T ≥ H ≥ Q = O, Z = T ≥ H ≥ Q = O gives only Z ≥ O, which does not make it definite. In O < H > Z ≥ Q > T, Z < H > O has opposite signs, which does not make it definite.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"reason-inequality-order-144","question":"In a row of children, Kabir is 13th from the left end and Meera is 9th from the right end. When they interchange their positions, Kabir becomes 21st from the left end. How many children are there in the row?","options":["33","28","29","30"],"answer":2,"explanation":"After the swap Kabir takes Meera's place, which is 9th from the right and now 21st from the left. Total = 21 + 9 − 1 = 29.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-145","question":"In a row of children, Kabir is 13th from the left end and Meera is 9th from the right end. When they interchange their positions, Kabir becomes 21st from the left end. How many children sit between Kabir and Meera?","options":["8","6","9","7"],"answer":3,"explanation":"Meera's original place is 21st from the left (Kabir takes it after the swap). Kabir is 13th, so the children between them occupy places 14 to 20: 7. (Total = 21 + 9 − 1 = 29.)","difficulty":"hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-146","question":"In a class of 52 students, Tara ranks 17th from the top. Vir ranks 9 places below Tara. What is Vir's rank from the bottom?","options":["27th","28th","26th","29th"],"answer":0,"explanation":"Vir's rank from the top = 17 + 9 = 26. From the bottom = 52 − 26 + 1 = 27.","difficulty":"easy","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-147","question":"In a row, Esha is 15th from the left end and Farah is 11th from the right end. Exactly 6 persons sit between them. What is the minimum possible number of persons in the row?","options":["32","18","17","19"],"answer":1,"explanation":"If Esha is to the left of Farah, the row has 15 + 6 + 11 = 32 persons. If Farah is to the left of Esha, Farah is 15 − 7 = 8th from the left, so the row has 8 + 11 − 1 = 18 persons. Minimum = 18.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-148","question":"Among the students who passed an examination, Sagar ranks 7th from the top and 24th from the bottom. Five students failed and three did not appear. How many students were enrolled in the class?","options":["35","30","38","39"],"answer":2,"explanation":"Passed students = 7 + 24 − 1 = 30. Enrolled = 30 + 5 failed + 3 absent = 38.","difficulty":"hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-149","question":"In a queue of 40 persons, Nikhil is 18th from the front and Om is 12 places behind Nikhil. Pari stands exactly midway between Nikhil and Om. What is Pari's position from the back?","options":["18th","16th","24th","17th"],"answer":3,"explanation":"Om is 30th from the front. Midway between 18 and 30 is position 24. From the back: 40 − 24 + 1 = 17.","difficulty":"hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-150","question":"Ajay, Bhanu, Chitra, Deepak and Esha have different heights. Chitra is taller than only Bhanu. Esha is taller than Ajay but shorter than Deepak. Who is the third tallest?","options":["Ajay","Esha","Chitra","Deepak"],"answer":0,"explanation":"Chitra being taller than only Bhanu puts Bhanu last and Chitra fourth. Deepak > Esha > Ajay fill the top three places, so the order is Deepak > Esha > Ajay > Chitra > Bhanu. The third tallest is Ajay.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-151","question":"Seven boxes P, Q, R, S, T, U and V have different weights. Q is heavier than S, which is heavier than P. T is heavier than Q, and R is lighter than P. U is heavier than T, and V is the fourth heaviest. Which box is the third heaviest?","options":["T","Q","U","S"],"answer":1,"explanation":"The chain is U > T > Q > S > P > R, six boxes in a fixed order. V is fourth heaviest, so it fits between them: U > T > Q > V > S > P > R. The third heaviest is Q.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-152","question":"If the words Caption, Capital, Capsule, Captain and Capable are arranged in dictionary order, which word comes fourth?","options":["Capital","Capsule","Captain","Caption"],"answer":2,"explanation":"Dictionary order: Capable, Capital, Capsule, Captain, Caption. The fourth word is Captain.","difficulty":"easy","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-153","question":"If the digits of the number 5926184 are arranged in descending order from left to right, how many digits will remain in their original positions?","options":["3","1","2","0"],"answer":3,"explanation":"Descending order gives 9865421. Comparing 5926184 with 9865421 position by position, no digit keeps the same place.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-154","question":"Thirty-five students stand in a row facing north. Xena is 14th from the left end. Yash is 9th to the right of Xena, and Zoya is 4th to the left of Yash. What is Zoya's position from the right end?","options":["17th","19th","16th","18th"],"answer":0,"explanation":"Yash is 14 + 9 = 23rd from the left, Zoya is 23 − 4 = 19th from the left, so from the right she is 35 − 19 + 1 = 17th.","difficulty":"hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
  {"id":"reason-inequality-order-155","question":"In a class, Karan ranks 6th from the top and 15th from the bottom among the boys. There are 3 fewer girls than boys. Lata ranks 8th from the bottom among the girls. What is Lata's rank from the top among the girls?","options":["9th","10th","11th","13th"],"answer":1,"explanation":"Boys = 6 + 15 − 1 = 20. Girls = 20 − 3 = 17. Lata's rank from the top among the girls = 17 − 8 + 1 = 10.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk · RRB NTPC"},
];

